"""Executable regression examples, preserving every original Python block."""
BLOCKS = ('import torch\n'
 'from torch.utils.data import DataLoader, TensorDataset\n'
 'from hyso.training import Trainer\n'
 'from hyso.performance import measure_gradient_diagnostics, GradientDiagnosticsProtocol\n'
 '\n'
 'model = torch.nn.Linear(3, 2)\n'
 'optimizer = torch.optim.AdamW(model.parameters(), lr=.01)\n'
 'trainer = Trainer(model, optimizer=optimizer, loss_fn=torch.nn.CrossEntropyLoss(),\n'
 '                  accum_steps=2, grad_clip=.1)\n'
 'train = DataLoader(TensorDataset(torch.ones(5, 3), torch.tensor([0, 1, 0, 1, 0])),\n'
 '                   batch_size=2)\n'
 'result = measure_gradient_diagnostics(trainer, train, epochs=1,\n'
 '    protocol=GradientDiagnosticsProtocol(max_attempts=10000, max_tensor_records=100000,\n'
 '                                         chunk_elements=65536, observe_postclip=True))\n'
 'data = result.to_dict()\n'
 'assert [r["samples"] for r in data["observations"]] == [4, 1]\n'
 'assert all(r["preclip"]["summary"]["finite"] for r in data["observations"])\n'
 'assert all(r["optimizer_executed"] for r in data["observations"])\n',)
